                      "ani",
                      "lang"
                    ]
                  }
                },
                "required": [
                  "data",
                  "call"
                ]
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "See original contract and test fixture"
          }
        }
      }
    },
    "/statement.week.decide": {
      "post": {
